package dev.openallay.runtime.forge1122;
import java.util.Base64;
public final class ObjectHolderPhaseTest {
    public static void main(String[] args) throws Exception {
        byte[] registry=Base64.getDecoder().decode("");
        byte[] helper=Base64.getDecoder().decode("");
        if(!ObjectHolderBridge.PHASE_REGISTRY_SHA.equals(ObjectHolderBridge.sha(registry))
                || !ObjectHolderBridge.PHASE_CLASS_SHA.equals(ObjectHolderBridge.sha(helper))) throw new AssertionError("Exact actual phase fixtures differ");
        byte[] registryOut=ObjectHolderBridge.patchRegistry(registry,true);
        byte[] helperOut=ObjectHolderBridge.patch(helper,true);
        java.util.Map<String,String> before=ObjectHolderBridge.methodInstructions(registry),after=ObjectHolderBridge.methodInstructions(registryOut);
        before.remove("scanClassForFields(Ljava/util/Map;Ljava/lang/String;Ljava/lang/String;Ljava/lang/Class;Z)V");after.remove("scanClassForFields(Ljava/util/Map;Ljava/lang/String;Ljava/lang/String;Ljava/lang/Class;Z)V");
        if(!before.equals(after))throw new AssertionError("Actual postForge non-scan methods changed");
        before=ObjectHolderBridge.methodInstructions(helper);after=ObjectHolderBridge.methodInstructions(helperOut);
        before.remove("makeWritable(Ljava/lang/reflect/Field;)Ljava/lang/reflect/Field;");after.remove("makeWritable(Ljava/lang/reflect/Field;)Ljava/lang/reflect/Field;");
        before.remove("setField(Ljava/lang/reflect/Field;Ljava/lang/Object;Ljava/lang/Object;)V");after.remove("setField(Ljava/lang/reflect/Field;Ljava/lang/Object;Ljava/lang/Object;)V");
        if(!before.equals(after))throw new AssertionError("Actual postForge unrelated helper methods changed");
        try {ObjectHolderBridge.patchRegistry(registry);throw new AssertionError("Phase input cannot match raw input gate");}catch(IllegalStateException expected){}
        try {ObjectHolderBridge.patch(helper);throw new AssertionError("Phase input cannot match raw input gate");}catch(IllegalStateException expected){}
        registry[registry.length-1]^=1;helper[helper.length-1]^=1;
        try {ObjectHolderBridge.patchRegistry(registry,true);throw new AssertionError("Changed phase must reject");}catch(IllegalStateException expected){}
        try {ObjectHolderBridge.patch(helper,true);throw new AssertionError("Changed phase must reject");}catch(IllegalStateException expected){}
        System.out.println("PASS actual run37519592481 exact postForge inputs; raw phase distinct; modified phase rejected; unrelated instructions unchanged");
    }
}
